// An action is a `git push`, a `gh` write, a write by a network client to GitHub, or a touch of the verdict store.
// A local command makes no action: an edit, a build, `git commit`, and a redirect stay allowed in every checkout.
// The reading compares the words of each simple command with fixed lists. It never scans prose.

import { GIT_VALUE_OPTIONS } from "../../../kernel/gitopts.ts";
import { parse } from "../../../kernel/shell.ts";
import { baseName, stripWrappers } from "../../../kernel/wrappers.ts";
import { netOf } from "./net.ts";
import { isDynamic, optionValue, touchesStore, under } from "./paths.ts";
import { ghLocal, readsOnly } from "./readonly.ts";

/** One action. */
export type Action =
  /** A word names the verdict store, in a command that is not a read. */
  | { kind: "store" }
  /** A `git push`. `remote` is the remote name or URL, or `undefined` for the default of the branch. */
  | {
      kind: "push";
      dir: string | undefined;
      remote: string | undefined;
      /** The folder or the remote has a shell expansion, so it is not in the text. */
      unknown: boolean;
    }
  /** A `gh` call that writes. `repo` is the `-R` value or the repository of a `gh api` endpoint. */
  | {
      kind: "gh";
      dir: string | undefined;
      repo: string | undefined;
      unknown: boolean;
    }
  /** A write by a network client to a GitHub host. `unclear` is set when a URL names no repository or has an expansion. */
  | { kind: "net"; repos: string[]; unclear: boolean };

/** The value of a flag: `-R x`, `-Rx`, `--repo x`, or `--repo=x`. */
const flagValue = (
  words: string[],
  short: string,
  long: string,
): string | undefined => {
  for (let i = 0; i < words.length; i++) {
    const w = words[i] as string;
    if (w === short || w === long) return words[i + 1];
    if (w.startsWith(`${long}=`)) return w.slice(long.length + 1);
    if (w.startsWith(short) && !w.startsWith("--"))
      return w.slice(short.length);
  }
  return undefined;
};

/** The repository that a `gh api` endpoint names, as `OWNER/REPO`. */
const apiRepo = (words: string[]): string | undefined => {
  for (const w of words) {
    const m = /^\/?repos\/([^/\s]+)\/([^/\s]+)/.exec(w);
    if (m) return `${m[1]}/${m[2]}`;
  }
  return undefined;
};

/** The folder of a `git` call after `-C`, whether a `-C` value is dynamic, and the index of the verb. */
const gitDir = (
  words: string[],
  dir: string | undefined,
): { dir: string | undefined; unknown: boolean; verb: number } => {
  let folder = dir;
  let unknown = false;
  let i = 1;
  while (i < words.length && (words[i] as string).startsWith("-")) {
    const opt = words[i] as string;
    if (opt === "-C") {
      const next = words[i + 1] ?? "";
      if (isDynamic(next)) unknown = true;
      else folder = under(folder, next);
    }
    i += GIT_VALUE_OPTIONS.has(opt) ? 2 : 1;
  }
  return { dir: folder, unknown, verb: i };
};

/** The options of `git push` that take a value in the next word. */
const PUSH_VALUE_OPTIONS: ReadonlySet<string> = new Set([
  "-o",
  "--push-option",
  "--receive-pack",
  "--exec",
]);

/** The remote of a `git push`: `--repo`, else the first operand. `dynamic` is set when it has an expansion. */
const pushRemote = (
  rest: string[],
): { remote: string | undefined; dynamic: boolean } => {
  let remote: string | undefined;
  for (let i = 0; i < rest.length; i++) {
    const w = rest[i] as string;
    if (w === "--repo") remote = rest[i + 1];
    else if (w.startsWith("--repo=")) remote = optionValue(w);
    else if (w.startsWith("-")) {
      if (PUSH_VALUE_OPTIONS.has(w)) i++;
    } else if (remote === undefined) remote = w;
  }
  return { remote, dynamic: remote !== undefined && isDynamic(remote) };
};

/** The actions of one simple command. */
const runOf = (
  head: string,
  words: string[],
  dir: string | undefined,
  unknownDir: boolean,
): Action[] => {
  const git =
    head === "git" ? gitDir(words, dir) : { dir, unknown: false, verb: 1 };
  const reads = netOf(head, words);
  const words2 = words.slice(1).map(optionValue);
  const touches = [git.dir ?? "", ...words2.map((w) => under(git.dir, w))].some(
    touchesStore,
  );
  const readOnly =
    reads === undefined
      ? readsOnly(head, words)
      : !reads.write && !reads.output;
  if (touches && !readOnly) return [{ kind: "store" }];
  if (head === "git" && words[git.verb] === "push") {
    const { remote, dynamic } = pushRemote(words.slice(git.verb + 1));
    return [
      {
        kind: "push",
        dir: git.dir,
        remote: dynamic ? undefined : remote,
        unknown: unknownDir || git.unknown || dynamic,
      },
    ];
  }
  if (head === "gh" && !readsOnly(head, words) && !ghLocal(words))
    return [
      {
        kind: "gh",
        dir,
        unknown: unknownDir,
        repo:
          flagValue(words, "-R", "--repo") ??
          (words[1] === "api" ? apiRepo(words) : undefined),
      },
    ];
  if (reads?.write && (reads.repos.length > 0 || reads.unclear))
    return [{ kind: "net", repos: reads.repos, unclear: reads.unclear }];
  return [];
};

/** The actions of `command`, in order. */
export const actionsOf = (command: string): Action[] => {
  const parsed = parse(command);
  const out: Action[] = [];
  let dir: string | undefined;
  let unknownDir = false;
  for (const argv of parsed.commands) {
    const words = stripWrappers(argv);
    const head = words[0] === undefined ? "" : baseName(words[0]);
    if (head === "cd") {
      const operand = words.slice(1).find((w) => !w.startsWith("-")) ?? "";
      if (operand === "-") dir = undefined;
      else if (isDynamic(operand)) unknownDir = true;
      else if (operand !== "") {
        dir = under(dir, operand);
        unknownDir = false;
      }
    } else if (head !== "") out.push(...runOf(head, words, dir, unknownDir));
  }
  for (const r of parsed.redirects) {
    if (isDynamic(r.target) || r.target.startsWith("/dev/")) continue;
    if (touchesStore(under(dir, r.target))) out.push({ kind: "store" });
  }
  return out;
};
